            examTag = "IISER IAT",

            chapterNumber = 15,

            title = "Body Fluids and Circulation",

            subtitle = "Blood Groups (ABO & Rh), Coagulation Cascade, Cardiac Cycle (0.8 s), Cardiac Output & ECG Wave Analysis",

            totalLessons = 6,

            completedLessons = 3,

            studyNotesCount = 9,

